      // createSecondProject creates the directory structure but registers it too
      // So we need a fresh path — create one directly via the API
      const secondPath = await daemon.createSecondProject();

      // The second project was already registered by createSecondProject
      // Verify it appears in the list
      const listResponse = await request.get(`${DAEMON_URL}/api/projects`);
      const listBody = await listResponse.json();
      const found = listBody.projects.find(
        (p: { path: string }) => p.path === secondPath
      );
      expect(found).toBeDefined();
      expect(found.path).toBe(secondPath);
    });

    // AC: @multi-directory-daemon ac-29 — direct POST /api/projects test
    test('POST /api/projects accepts {path} body and returns {success, project}', async ({
      request,
      daemon,
    }) => {
      // We need a path with .kspec/ structure — use daemon.tempDir + a subdirectory
      // The fixture tempDir already has .kspec/ set up, so register a variant
      // Use the second project helper which sets up the proper structure
      const { mkdirSync, writeFileSync } = await import('fs');
      const { join } = await import('path');
      const { tmpdir } = await import('os');

      // Create a minimal valid kspec project directory
      const freshProjectPath = join(tmpdir(), `kspec-e2e-fresh-${Date.now()}`);
      const freshKspecDir = join(freshProjectPath, '.kspec');
      mkdirSync(freshKspecDir, { recursive: true });

      // Minimal kynetic.yaml
      writeFileSync(
        join(freshKspecDir, 'kynetic.yaml'),
        `kynetic: "1.0"\nproject: Fresh Test Project\n`
      );

      // project.tasks.yaml
      writeFileSync(
        join(freshKspecDir, 'project.tasks.yaml'),
        `tasks: []\n`
      );

      // Set up shadow worktree simulation
      const { execSync } = await import('child_process');
      execSync('git init', { cwd: freshProjectPath, stdio: 'ignore' });
      execSync('git config user.email "test@test.com"', { cwd: freshProjectPath, stdio: 'ignore' });
      execSync('git config user.name "Test"', { cwd: freshProjectPath, stdio: 'ignore' });

      const gitWorktreesDir = join(freshProjectPath, '.git', 'worktrees', '-kspec');
      mkdirSync(gitWorktreesDir, { recursive: true });
      writeFileSync(join(freshKspecDir, '.git'), `gitdir: ${gitWorktreesDir}\n`);
      writeFileSync(join(gitWorktreesDir, 'gitdir'), `${join(freshProjectPath, '.git')}\n`);
      writeFileSync(join(gitWorktreesDir, 'HEAD'), 'ref: refs/heads/kspec-meta\n');

      try {
        // AC: @multi-directory-daemon ac-29 — POST with {path} body
        const response = await request.post(`${DAEMON_URL}/api/projects`, {
